	wire := wireState{
		Version:  st.Version,
		Time:     st.Time,
		HasTime:  st.HasTime,
		Headers:  headers,
		Records:  st.Records,
		Consumed: consumed,
	}
	data, err := json.MarshalIndent(wire, "", "  ")
	if err != nil {
		return fmt.Errorf("encode state: %w", err)
	}

	tmp := filepath.Join(s.dir, stateFileName+".tmp")
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
